import type { SVGProps } from "react";

/**
 * Marcas de pago y de plataformas.
 *
 * Los trazados provienen de los contornos oficiales publicados por cada marca
 * (los mismos que distribuye Simple Icons bajo CC0), no de aproximaciones
 * dibujadas a mano ni de texto en Arial. Cada marca lleva `role="img"` y
 * `aria-label`, y se usa únicamente para identificar el medio de pago o el
 * servicio conectado, que es el uso nominativo que las guías de marca de
 * Stripe, Mercado Pago, Visa y Mastercard permiten.
 */

type MarkProps = SVGProps<SVGSVGElement> & { compact?: boolean };

