// --- Marcas de pago --------------------------------------------------------

/** Visa — logotipo oficial, azul corporativo #1434CB. */
export function VisaMark({ className, ...props }: MarkProps) {
  return (
    <svg viewBox="0 8.1 24 7.9" role="img" aria-label="Visa" className={className} {...props}>
      <path fill="#1434CB" d={D_VISA} />
    </svg>
  );
}

/**
 * Mastercard — símbolo oficial de los dos círculos entrelazados con la
 * intersección en naranja. En modo `compact` se muestra sólo el símbolo, que es
 * la forma que la marca autoriza para listados de medios de pago estrechos.
 */
export function MastercardMark({ className, compact = false, ...props }: MarkProps) {
  return (
    <svg
      viewBox={compact ? "0 0 48 30" : "0 0 118 30"}
      role="img"
      aria-label="Mastercard"
      className={className}
      {...props}
    >
      <circle cx="18" cy="15" r="14" fill="#EB001B" />
      <circle cx="34" cy="15" r="14" fill="#F79E1B" />
      <path
        fill="#FF5F00"
        d="M26 4.36a13.97 13.97 0 0 1 0 21.28 13.97 13.97 0 0 1 0-21.28Z"
      />
      {!compact && (
        <text
          x="54"
          y="20"
          fill="currentColor"
          fontSize="13.5"
          fontWeight="600"
          letterSpacing="-0.4"
          fontFamily="var(--font-body)"
        >
          mastercard
        </text>
      )}
    </svg>
  );
}

/** American Express — marca monocroma sobre el azul corporativo #006FCF. */
export function AmexMark({ className, ...props }: MarkProps) {
  return (
    <svg viewBox="0 0 24 24" role="img" aria-label="American Express" className={className} {...props}>
      <path fill="#006FCF" d={D_AMEX_MONO} />
    </svg>
  );
}

/**
 * Stripe — glifo oficial de la «S» sobre el morado de marca #635BFF, con el
 * nombre a su lado. La combinación símbolo + nombre es la forma habitual de
 * declarar la pasarela en una lista de medios de pago.
 */
export function StripeMark({ className, compact = false, ...props }: MarkProps) {
  return (
    <svg
      viewBox={compact ? "0 0 30 30" : "0 0 108 30"}
      role="img"
      aria-label="Stripe"
      className={className}
      {...props}
    >
      <rect width="30" height="30" rx="7" fill="#635BFF" />
      <g transform="translate(7.5 3) scale(0.625)">
        <path fill="#ffffff" d={D_STRIPE} />
      </g>
      {!compact && (
        <text
          x="37"
          y="21"
          fill="currentColor"
          fontSize="16"
          fontWeight="700"
          letterSpacing="-0.6"
          fontFamily="var(--font-body)"
        >
          Stripe
        </text>
      )}
    </svg>
  );
}

/** Mercado Pago — símbolo oficial del apretón de manos sobre el azul #00B1EA. */
export function MercadoPagoMark({ className, compact = false, ...props }: MarkProps) {
  return (
    <svg
      viewBox={compact ? "0 0 30 30" : "0 0 104 30"}
      role="img"
      aria-label="Mercado Pago"
      className={className}
      {...props}
    >
      <g transform="translate(0 1.5) scale(1.12)">
        <path fill="#00B1EA" d={D_MERCADO} />
      </g>
      {!compact && (
        <>
          <text
            x="32"
            y="14.5"
            fill="currentColor"
            fontSize="12.5"
            fontWeight="700"
            letterSpacing="-0.3"
            fontFamily="var(--font-body)"
          >
            mercado
          </text>
          <text
            x="32"
            y="27"
            fill="currentColor"
            fontSize="12.5"
            fontWeight="700"
            letterSpacing="-0.3"
            fontFamily="var(--font-body)"
          >
            pago
          </text>
        </>
      )}
    </svg>
  );
}

/**
 * Mercado Libre — mismo apretón de manos del ecosistema Meli, sobre el amarillo
 * corporativo #FFE600 que es el que lo identifica frente a Mercado Pago.
 */
export function MercadoLibreMark({ className, compact = false, ...props }: MarkProps) {
  return (
    <svg
      viewBox={compact ? "0 0 36 30" : "0 0 110 30"}
      role="img"
      aria-label="Mercado Libre"
      className={className}
      {...props}
    >
      <rect width="36" height="28" y="1" rx="7" fill="#FFE600" />
      <g transform="translate(4.5 3.5) scale(1.12)">
        <path fill="#2D3277" d={D_MERCADO} />
      </g>
      {!compact && (
        <>
          <text
            x="42"
            y="14.5"
            fill="currentColor"
            fontSize="12.5"
            fontWeight="700"
            letterSpacing="-0.3"
            fontFamily="var(--font-body)"
          >
            mercado
          </text>
          <text
            x="42"
            y="27"
            fill="currentColor"
            fontSize="12.5"
            fontWeight="700"
            letterSpacing="-0.3"
            fontFamily="var(--font-body)"
          >
            libre
          </text>
        </>
      )}
    </svg>
  );
}

